.fub__map{max-width:1200px;margin:0 auto;padding:0 32px;}
.fub__map iframe{width:100%;height:380px;border:1px solid rgba(43,38,34,.3);display:block;filter:grayscale(1) contrast(.92) sepia(.16);}
.fub__cols{max-width:1200px;margin:40px auto 0;padding:0 32px;display:grid;grid-template-columns:repeat(4,1fr);gap:32px;}
.fub__col{border-top:1px solid rgba(43,38,34,.3);padding-top:16px;}
.fub h3.fub__ch{font-family:"IBM Plex Mono",monospace !important;font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:#571726;font-weight:400;margin:0 0 12px;}
.fub__col p{font-family:"Jost","Helvetica Neue",Helvetica,sans-serif !important;font-size:14px;line-height:1.75;color:#4A423B;margin:0;}
.fub p.fub__cta-wrap{max-width:1200px;margin:34px auto 0;padding:0 32px;}
.fub a.fub__cta{display:inline-block;font-family:"IBM Plex Mono",monospace !important;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#571726 !important;border-bottom:1px solid #571726;padding:0 0 4px;text-decoration:none !important;}
.fub a.fub__cta:hover{color:#2B2622 !important;border-color:#2B2622;}
@media (max-width:899px){
.fub__cols{grid-template-columns:1fr 1fr;gap:24px;}
.fub h2.fub__h2{font-size:34px;}
.fub__map iframe{height:260px;}
.fub__head,.fub__map,.fub__cols,.fub p.fub__cta-wrap{padding-left:24px;padding-right:24px;}
}

