[class*="hero-b---plate-and-note"] [class*="carousel-item-"]{height:auto !important;min-height:0 !important;}
[class*="hero-b---plate-and-note"] [class*="carousel-item-"] .full-width.position-relative{height:auto !important;min-height:0 !important;overflow:visible !important;}
[class*="hero-b---plate-and-note"] [class*="carousel-item-"] img{width:100% !important;height:auto !important;display:block !important;object-fit:contain !important;}
